 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    # Tile grid into demonstrated component shapes: 2x2 blocks are color 1;
    # L triominoes color according to missing corner (TL=2, TR=4, BL=3, BR=2).
    placements=[]
    for r in range(h-1):
        for c in range(w-1):
            square={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
            placements.append((square,1))
            for missing,col in (((r,c),2),((r,c+1),4),((r+1,c),3),((r+1,c+1),2)):
                placements.append((square-{missing},col))
    valid=[(s,col) for s,col in placements if s<=cells]
    # Exact-cover search, preferring larger tiles and square tile where possible.
    def go(rem):
        if not rem:return []
        p=min(rem,key=lambda q:sum(s<=rem for s,_ in valid if q in s))
        opts=[(s,col) for s,col in valid if p in s and s<=rem]
        opts.sort(key=lambda x:(-len(x[0]), x[1]))
        for s,col in opts:
            ans=go(rem-s)
            if ans is not None:return [(s,col)]+ans
        return None
    tiles=go(cells)
    out=[[0]*w for _ in range(h)]
    if tiles:
        for s,col in tiles:
            for r,c in s:out[r][c]=col
    return out
